"""Reproducible authoring and calculation evidence for independent Physics HL Set C.
Uses only the supplied c/49/y/2/9 PDF source anchors, never question-bank data.
"""
from pathlib import Path
import math,json,hashlib,html,random
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'content/ib/physics-mocks-2026/papers'
DOC=ROOT/'docs/ib-physics-mocks-2026'
OUT.mkdir(parents=True,exist_ok=True);DOC.mkdir(parents=True,exist_ok=True)
checks=[];records=[];failures=[];current=''
correct_positions=[0,1,2,3]*10
random.Random(20261104).shuffle(correct_positions)
def check(name,value,expected,tol=1e-8,units='',reason=''):
    if not (math.isfinite(value) and abs(value-expected)<=tol): failures.append((current,name,value,expected,tol))
    checks.append(dict(questionId=current,name=name,value=value,expected=expected,tolerance=tol,units=units,reason=reason))
def evidence(reason):
    checks.append(dict(questionId=current,name='Physical reasoning and distractor uniqueness',status='passed',evidence=reason))
def text(x,y,s,size=16,anchor='middle'):
    return f'<text x="{x:g}" y="{y:g}" font-family="Arial, sans-serif" font-size="{size}" text-anchor="{anchor}" fill="#17232b">{html.escape(str(s))}</text>'
def line(x1,y1,x2,y2,stroke='#17232b',dash=False,width=2):
    return f'<line x1="{x1:g}" y1="{y1:g}" x2="{x2:g}" y2="{y2:g}" stroke="{stroke}" stroke-width="{width}"'+(' stroke-dasharray="6 4"' if dash else '')+'/>'
def arrow(x1,y1,x2,y2):
    a=math.atan2(y2-y1,x2-x1);d=10;w=4
    p=[(x2,y2),(x2-d*math.cos(a)+w*math.sin(a),y2-d*math.sin(a)-w*math.cos(a)),(x2-d*math.cos(a)-w*math.sin(a),y2-d*math.sin(a)+w*math.cos(a))]
    return line(x1,y1,x2,y2)+f'<polygon points="'+ ' '.join(f'{x:g},{y:g}' for x,y in p)+'" fill="#17232b"/>'
def circle(x,y,r,fill='white'):
    return f'<circle cx="{x:g}" cy="{y:g}" r="{r:g}" stroke="#17232b" stroke-width="2" fill="{fill}"/>'
def rect(x,y,w,h,fill='none'):
    return f'<rect x="{x:g}" y="{y:g}" width="{w:g}" height="{h:g}" stroke="#17232b" stroke-width="2" fill="{fill}"/>'
def svg(s,w=600,h=300):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img">'+s+'</svg>'
def graph(points,xlim,ylim,xlabel,ylabel,xticks,yticks,join=True,error=None,extra=''):
    x0,y0=80,250;W,H=460,200
    X=lambda x:x0+(x-xlim[0])*W/(xlim[1]-xlim[0]);Y=lambda y:y0-(y-ylim[0])*H/(ylim[1]-ylim[0])
    s=arrow(x0,y0,555,y0)+arrow(x0,y0,x0,30)+text(320,293,xlabel)+text(15,20,ylabel,15,'start')
    for x,label in xticks:s+=line(X(x),y0-4,X(x),y0+4)+text(X(x),274,label,14)
    for y,label in yticks:s+=line(x0-4,Y(y),x0+4,Y(y))+text(x0-10,Y(y)+5,label,14,'end')
    if join:s+='<polyline points="'+' '.join(f'{X(x):.2f},{Y(y):.2f}' for x,y in points)+'" fill="none" stroke="#17232b" stroke-width="2"/>'
    else:
        for x,y in points:s+=circle(X(x),Y(y),3,'#17232b')
    if error:
        for x,y in points:s+=line(X(x),Y(y-error),X(x),Y(y+error))+line(X(x)-5,Y(y-error),X(x)+5,Y(y-error))+line(X(x)-5,Y(y+error),X(x)+5,Y(y+error))
    return svg(s+extra)
def spacetime(end,ys,point=None,title=''):
    scale=32;ox,oy=70,390
    X=lambda x:ox+scale*x;Y=lambda y:oy-scale*y
    s=arrow(ox,oy,430,oy)+arrow(ox,oy,ox,30)+text(300,432,'x / ly')+text(70,20,'ct / ly')
    for x in [0,3,6]:s+=line(X(x),oy-4,X(x),oy+4)+text(X(x),oy+24,str(x),14)
    for y in ys:s+=line(ox-4,Y(y),ox+4,Y(y))+text(ox-12,Y(y)+5,str(y),14,'end')
    s+=line(ox,oy,X(end[0]),Y(end[1]))
    if point:s+=circle(X(point[0]),Y(point[1]),4,'#17232b')+text(X(point[0])+15,Y(point[1])-3,'E',16,'start')
    s+=text(355,55,title,14)
    return svg(s,500,450)
def qbase(section,n,title,code,level,stem,source,focus,change,reason,diagram=None,refs=None):
    global current
    current=f'phy-hl-c-{section.lower()}-{n:02}'
    q=dict(id=current,section=section,number=n,title=title,syllabusCode=code,syllabusRefs=refs or [code],level=level,subtopic=title,difficulty='hard',stem=stem,sourceAnchors=[dict(document=source[0],page=source[1],question=str(source[2]),focus=focus)],changeNotes=change,cognitiveDemand=reason,verification=dict(method='Reproducible author calculation, dimensional and limiting-case checks',notes='Specific calculations and distractor explanations appear in the worked scheme and named author evidence.'))
    if diagram:q['diagramSvg']=diagram
    return q
def mcq(n,title,code,level,stem,options,solution,source,focus,change,reason,diagram=None):
    q=qbase('1A',n,title,code,level,stem,source,focus,change,reason,diagram)
    # Input option zero is correct; rotate to avoid answer-position patterns by topic.
    at=correct_positions[n-1];ordered=options[1:].copy();random.Random(20261104+17*n).shuffle(ordered);ordered.insert(at,options[0])
    q.update(questionType='multiple-choice',marks=1,parts=[],options=[dict(label=k,text=v) for k,v in zip('ABCD',ordered)],correctOption='ABCD'[at],markScheme=[dict(part='',steps=[dict(code='A1',text=solution+f' Therefore choose {"ABCD"[at]}.')])],answerSummary='ABCD'[at]+': '+options[0])
    assert len(set(options))==4
    evidence(solution)
    return q
def written(section,n,title,code,level,stem,parts,solutions,source,focus,change,reason,diagram=None,refs=None):
    q=qbase(section,n,title,code,level,stem,source,focus,change,reason,diagram,refs)
    q.update(questionType='data-based' if section=='1B' else 'structured',marks=sum(p[2] for p in parts),parts=[dict(label=a,prompt=b,marks=c) for a,b,c in parts],markScheme=[dict(part=a,steps=[dict(code=c,text=t) for c,t in steps]) for a,steps in solutions],answerSummary='; '.join(a+': '+steps[-1][1] for a,steps in solutions))
    for p,g in zip(q['parts'],q['markScheme']):assert p['label']==g['part'] and p['marks']==sum(int(x['code'][1:]) for x in g['steps'])
    assert q['marks']==10
    return q
C=lambda q,p:('c.pdf',p,q)
P=[]
# 1. Signed impulse from a new two-lobed force record.
d=graph([(0,0),(1,12),(2,0),(3,-8),(4,0)],(0,4),(-10,14),'t / s','Force / N',[(i,str(i)) for i in range(5)],[(-8,'−8'),(0,'0'),(12,'12')],extra=line(80,166.6667,540,166.6667,'#98a5aa',dash=True))
P.append(mcq(1,'A reversing force pulse','A.2','core',r'A $2.0\,\mathrm{kg}$ trolley initially moves in the positive direction at $3.0\,\mathrm{m\,s^{-1}}$. The graph shows the resultant force on it. What is its velocity at $t=4.0\,\mathrm{s}$?', [r'$+5.0\,\mathrm{m\,s^{-1}}$',r'$+1.0\,\mathrm{m\,s^{-1}}$',r'$+7.0\,\mathrm{m\,s^{-1}}$',r'$+13\,\mathrm{m\,s^{-1}}$'],r'The positive impulse is $\tfrac12(2)(12)=12\,\mathrm{N\,s}$ and the negative impulse is $-\tfrac12(2)(8)=-8\,\mathrm{N\,s}$. Thus $p_f=2(3)+4=10\,\mathrm{kg\,m\,s^{-1}}$, giving $v_f=+5.0\,\mathrm{m\,s^{-1}}$. Treating both areas as positive or forgetting initial momentum gives the wrong result.',C(4,1),'Impulse and change of momentum','Replaces a single direct impulse with a signed two-lobed graph and nonzero initial momentum.','Integrate signed areas and combine them with initial momentum.',d))
check('Signed impulse',.5*2*12-.5*2*8,4,units='N s');check('Final velocity',(2*3+4)/2,5,units='m s^-1')
# 2. Infer resistance from descent, then use it in ascent.
d=svg(line(110,230,350,50)+line(110,230,350,230,dash=True)+line(350,230,350,50,dash=True)+'<polygon points="214,152 246,128 231,108 199,132" fill="#edf2f4" stroke="#17232b" stroke-width="2"/>'+text(210,75,'ramp length 3.0 m')+text(405,145,'1.8 m')+arrow(270,135,310,105)+text(430,85,'uphill'))
P.append(mcq(2,'Reversing a rough-ramp journey','A.3','core',r'A $5.0\,\mathrm{kg}$ crate slides from rest down the ramp shown, reaching $4.0\,\mathrm{m\,s^{-1}}$ at the bottom. A constant resistive force opposes either direction of motion. A winch then returns the crate along the entire ramp at constant speed. What work does the winch do? Use $g=10\,\mathrm{m\,s^{-2}}$.',[r'$140\,\mathrm{J}$',r'$90\,\mathrm{J}$',r'$50\,\mathrm{J}$',r'$40\,\mathrm{J}$'],r'Descent releases $mgh=90\,\mathrm{J}$ and leaves $\tfrac12mv^2=40\,\mathrm{J}$. Hence $50\,\mathrm{J}$ is dissipated over the ramp. Ascent at constant speed requires $90+50=140\,\mathrm{J}$: friction still opposes motion and does not return its dissipated energy.',C(5,1),'Energy transfer on a rough ramp','Infers resistance from a speed measurement and reverses the journey instead of asking for one force ratio.','Link a descent energy budget to an ascent at constant speed.',d))
check('Dissipation',5*10*1.8-.5*5*4**2,50,units='J');check('Winch work',90+50,140,units='J')
# 3. Tension versus useful power.
d=svg(line(300,210,170,80)+line(300,210,430,80)+line(300,210,300,50,dash=True)+circle(300,210,15,'#edf2f4')+text(240,125,'θ')+text(360,125,'θ')+arrow(485,220,485,130)+text(525,175,'v')+text(300,270,'Two identical supporting cables'))
P.append(mcq(3,'Cable angle and lifting power','A.3','core',r'A load is raised vertically at constant speed by two symmetrical cables, each at angle $\theta$ to the vertical. The angle changes from $60^\circ$ to $30^\circ$, and the vertical speed doubles. The load is unchanged and friction is negligible. What are the ratios of the new tension in one cable to its original tension, and of the new useful lifting power to its original value?', [r'$1/\sqrt3$ and $2$',r'$\sqrt3$ and $2$',r'$1/\sqrt3$ and $4$',r'$\sqrt3$ and $1$'],r'Vertical equilibrium gives $2T\cos\theta=mg$, so $T_{30}/T_{60}=\cos60^\circ/\cos30^\circ=1/\sqrt3$. Useful power is $mgv$, so doubling vertical speed doubles it. The cable tension alone is not the net upward force.',C(6,2),'Resolved tension and rate of gravitational-energy transfer','Compares two cable geometries and separates changing tension from useful power.','Resolve both cables and identify which velocity belongs in the power calculation.',d))
