P.append(written('1B',1,'A calibrated metal-wire investigation','B.5','core',r'A laboratory group measures the resistance of an insulated metal wire immersed in a slowly cooling, stirred water bath. The graph shows synthetic laboratory data. All resistance error bars are $\pm0.020\,\Omega$; temperature uncertainty is negligible for parts (a)–(d). At the missing thermometer reading of $50.0^\circ\mathrm C$, the wire potential difference is $0.840\,\mathrm V$ and current is $0.250\,\mathrm A$. The wire length is $(2.00\pm0.01)\,\mathrm m$ and its diameter is $(0.400\pm0.004)\,\mathrm{mm}$; thermal expansion is negligible.',[
 ('a',r'Calculate the resistance at the missing data point.',1),
 ('b',r'Using the points at $20.0^\circ\mathrm C$ and $80.0^\circ\mathrm C$, determine the best gradient of resistance against thermometer reading and its uncertainty from the steepest and shallowest endpoint lines.',2),
 ('c',r'Calculate the resistivity at the $50.0^\circ\mathrm C$ thermometer reading.',2),
 ('d',r'Use maximum fractional uncertainties to state the resistivity at this reading with its absolute uncertainty and SI unit.',2),
 ('e',r'An ice–water check subsequently gives a thermometer reading of $-1.5^\circ\mathrm C$. Identify the error type and describe how correcting it changes the horizontal positions of all points and the gradient.',2),
 ('f',r'State one reason for stirring the bath while readings are taken.',1)], [
 ('a',[('A1',r'$R=V/I=0.840/0.250=3.36\,\Omega$.')]),
 ('b',[('A1',r'$g=(3.72-3.00)/(80-20)=0.0120\,\Omega\,{}^\circ\mathrm C^{-1}$.'),('A1',r'$g_{\max}=(3.74-2.98)/60=0.01267$ and $g_{\min}=(3.70-3.02)/60=0.01133\,\Omega\,{}^\circ\mathrm C^{-1}$; half the range gives $\Delta g=0.00067\,\Omega\,{}^\circ\mathrm C^{-1}$. Accept equivalent clearly drawn limiting lines.')]),
 ('c',[('M1',r'$A=\pi d^2/4=\pi(0.400\times10^{-3})^2/4=1.2566\times10^{-7}\,\mathrm{m^2}$, and $\rho=RA/L$.'),('A1',r'$\rho=3.36(1.2566\times10^{-7})/2.00=2.11\times10^{-7}\,\Omega\,\mathrm m$.')]),
 ('d',[('M1',r'$\Delta\rho/\rho=\Delta R/R+2\Delta d/d+\Delta L/L=0.020/3.36+2(0.004/0.400)+0.01/2.00=0.03095$.'),('A1',r'$\Delta\rho=6.53\times10^{-9}\,\Omega\,\mathrm m$, so quote $(2.11\pm0.07)\times10^{-7}\,\Omega\,\mathrm m$; a consistently rounded uncertainty of $0.065$ or $0.07$ in these units is acceptable.')]),
 ('e',[('R1',r'The constant thermometer zero offset is systematic. Correct true temperatures are $1.5^\circ\mathrm C$ greater than the readings.'),('R1',r'Every point moves $1.5^\circ\mathrm C$ to the right, with its resistance unchanged. Temperature differences, and therefore the gradient, are unchanged.')]),
 ('f',[('R1',r'Stirring reduces temperature gradients in the water so the thermometer and wire are at approximately the same temperature. Accept an equivalent specific thermal-equilibration explanation.')])],('y.pdf',4,2),'Wire resistance against bath temperature, geometry uncertainty and thermometer calibration','New full synthetic dataset, a diameter rather than a supplied area, endpoint-gradient uncertainty and a larger measured calibration offset.','Combine electrical measurement, graph uncertainty, squared-diameter propagation and a systematic calibration correction.',d,refs=['B.5','B.1','Tools']))
check('Missing resistance',.840/.250,3.36,units='ohm');check('Best resistance gradient',(3.72-3)/60,.012,units='ohm per deg C');check('Maximum gradient',(3.74-2.98)/60,.0126666666667,1e-12);check('Gradient uncertainty',(.0126666666667-.0113333333333)/2,.0006666666667,1e-12)
area=math.pi*(.400e-3)**2/4;rho=3.36*area/2;frac=.020/3.36+2*.004/.400+.01/2
check('Wire cross-sectional area',area,1.2566370614359172e-7,1e-18,units='m^2');check('Wire resistivity',rho,2.111150263212341e-7,1e-18,units='ohm m');check('Maximum fractional resistivity uncertainty',frac,.030952380952380953,1e-12);check('Absolute resistivity uncertainty',rho*frac,6.534512719466768e-9,1e-18,units='ohm m');evidence('A constant +1.5 degree correction changes no temperature difference, so no gradient. Stirring addresses spatial gradients, not meter precision.')
